}

.right {
	float: right;
}

.mounthead h3 {
	float: left;
	margin-bottom: 0px;
	border-bottom: none;
}

.mountcont {
	border-top: 1px groove #ACACAC;
	clear: both;
}

ul.mountlist {
	margin: 0;
	padding: 0;
	list-style: none;
	text-align: right;
}

.mountlist li {
	display: inline;
}

a.play {
	padding-left: 22px;
	margin-left: 25px;
	border: none;
	background: transparent url(/tunein.png) no-repeat scroll left center;
	background-size: auto 100%;
}

a.auth {
	padding-left: 22px;
	margin-left: 25px;
	border: none;
	background: transparent url(/key.png) no-repeat scroll left top;
	background-size: auto 100%;
}

/* Admin navigation */

ul.nav {
	margin: 0;
	padding: 5px 0 10px 0;
	clear: both;
	list-style: none;
	text-align: center;
}

ul.nav li {
	display: inline;
}

ul.nav li a {
	border: none;
	display: inline-block;
	padding: .2em .7em;
	margin-top: .2em;
	background-color: #333;
	white-space: nowrap;
}

