	white-space: nowrap;
}

ul.nav li a:hover {
	color: #fff;
}

/* Footer */

#footer {
	border-top: 1px groove #ACACAC;
	margin-top: 20px;
	font-size: 80%;
}

@media (max-width: 800px) {

	body {
 padding: 0;
	}

	.roundbox {
 width: auto;
 border-radius: 0;
	}

	.roundbox table.yellowkeys tr td {
 display: block;
 padding: 5px 5px 0 0;
	}

	.roundbox table.yellowkeys tr td:last-child {
 margin-bottom: 5px;
 margin-left: 5px;
	}

	.scrolltable {
 overflow: auto;
	}

}

@media (max-width: 320px) {

	ul.nav, #menu ul {
 display: block;
	}

	ul.nav li, #menu ul li {
 float: none;
	}

	ul.nav li a, #menu ul li a {
 display: block;
	}

	ul.nav li + li, #menu ul li + li {
 border-top: 1px solid #ACACAC;
	}

	a.play {
 margin-left: 15px;
	}

}

